/* materials.c - CPU texture synthesis, run on the console at boot.
 *
 * Two 64x64 4bpp textures with a 16-entry CLUT each, generated by two
 * genuinely different algorithms:
 *
 *   SOIL  - a cellular (Worley) field. Feature points are scattered on a
 *           jittered lattice; each texel takes the two nearest distances and
 *           darkens where they are close together, which is what draws the
 *           crack network between clods. Grain is added from value noise.
 *
 *   PETAL - a parametric vein field in UV. Veins fan out from the claw at
 *           the base of the blade along the ribbon's own u/v parameters, so
 *           they follow the surface when it bends instead of sliding over it
 *           like a world-space pattern would.
 *
 * Both are stored as modulation maps centred on 128, because the GPU computes
 * texel * vertex_colour / 128 for a textured polygon. The vertex colour
 * carries the lighting; the texture only carries the pattern. That keeps one
 * texture valid from the blue hour to moonlight and means the day/night CLUT
 * update is a 16-halfword write, not a re-synthesis.
 */
#include "materials.h"
#include "fixed.h"
#include "platform.h"
#include "render.h"

#define TEX_W 64
#define TEX_H 64

/* VRAM layout. The framebuffers own x 0..319, y 0..479; everything from
 * x 320 up is free, so the texture page sits at x 640 well clear of them. */
#define TEX_PAGE_X 640
#define TEX_PAGE_Y 0
#define SOIL_U     0
#define PETAL_U    64
#define CLUT_X     640
#define SOIL_CLUT_Y  200
#define PETAL_CLUT_Y 201

/* 4bpp: four texels per halfword, so a 64-wide texture is 16 halfwords. */
static u16 g_soil[TEX_H][TEX_W / 4];
static u16 g_petal[TEX_H][TEX_W / 4];
static u16 g_clut_soil[16];
static u16 g_clut_petal[16];

static u32 g_tpage;

static inline void put4(u16 *row, int x, int idx)
{
    int w = x >> 2, sh = (x & 3) * 4;
    row[w] = (u16)((row[w] & ~(0xF << sh)) | ((idx & 0xF) << sh));
}

/* ---- SOIL: cellular distance field ------------------------------------- */

#define FEAT_N 20

static void synth_soil(void)
{
    s16 fx[FEAT_N], fy[FEAT_N];
    int i, x, y;

    for (i = 0; i < FEAT_N; i++) {
        u32 h = di_hash2(DI_RS_MATERIAL, i, 0);
        fx[i] = (s16)(h % TEX_W);
        fy[i] = (s16)((h >> 9) % TEX_H);
    }

    for (y = 0; y < TEX_H; y++) {
        for (x = 0; x < TEX_W; x++) {
            s32 d1 = 1 << 20, d2 = 1 << 20;
            s32 v, grain, crack;
            for (i = 0; i < FEAT_N; i++) {
                /* Toroidal distance so the tile repeats seamlessly. */
                s32 dx = x - fx[i], dy = y - fy[i];
                s32 dsq;
                if (dx >  TEX_W / 2) dx -= TEX_W;
                if (dx < -TEX_W / 2) dx += TEX_W;
                if (dy >  TEX_H / 2) dy -= TEX_H;
                if (dy < -TEX_H / 2) dy += TEX_H;
                dsq = dx * dx + dy * dy;
                if (dsq < d1) { d2 = d1; d1 = dsq; }
                else if (dsq < d2) { d2 = dsq; }
            }
            /* Cracks live where the two nearest features are equidistant. */
            crack = (s32)di_isqrt((u32)d2) - (s32)di_isqrt((u32)d1);
            crack = ONE - DI_CLAMP(crack * (ONE / 5), 0, ONE);
            crack = fmul(crack, fmul(crack, crack));

            grain = di_fbm2(DI_RS_MATERIAL + 4, x * 64, y * 64, 8, 3);

            v = 128 + fmul(grain, 34) + fmul(crack, -74);
            /* Clods catch a little more light on their crowns. */
            v += fmul(ONE - DI_CLAMP(d1 * (ONE / 160), 0, ONE), 22);
            put4(g_soil[y], x, 1 + (DI_CLAMP(v, 0, 255) * 15) / 256);
        }
    }
}

/* ---- PETAL: parametric vein field -------------------------------------- */

static void synth_petal(void)
{
    int x, y;
    for (y = 0; y < TEX_H; y++) {
        for (x = 0; x < TEX_W; x++) {
            /* u runs along the blade, v across it. */
            s32 u = (x * ONE) / TEX_W;
            s32 vv = ((y - TEX_H / 2) * ONE) / (TEX_H / 2);   /* -ONE..ONE */
            s32 ang, vein, edge, v;

            /* Veins fan from the claw: the angular coordinate about the base
             * of the blade, so they converge where the petal narrows. */
            ang = di_atan2(vv, u + 400);
            vein = fcos(ang * 11);
            vein = DI_ABS(vein);
            vein = fmul(vein, vein);
            vein = fmul(vein, vein);
            vein = fmul(vein, vein);          /* sharpen into thin lines */

            /* The blade is paler toward the rim and at the very tip. */
            edge = fmul(DI_ABS(vv), DI_ABS(vv));

            v = 124 + fmul(vein, -46) + fmul(edge, 52)
                    + fmul(di_noise2(DI_RS_MATERIAL + 9, x * 48, y * 48, 7), 10);
            /* A soft bright flare down the midrib. */
            v += fmul(ONE - DI_CLAMP(DI_ABS(vv) * 6, 0, ONE), 20);
            put4(g_petal[y], x, 1 + (DI_CLAMP(v, 0, 255) * 15) / 256);
        }
    }
}

/* Build a 16-entry ramp. Index 0 stays transparent, which is why every texel
 * above is written as 1 + something. */
static void build_clut(u16 *clut, s32 r0, s32 g0, s32 b0, s32 r1, s32 g1, s32 b1)
{
    int i;
    clut[0] = 0;
    for (i = 1; i < 16; i++) {
        s32 t = ((i - 1) * ONE) / 14;
        s32 r = flerp(r0, r1, t), g = flerp(g0, g1, t), b = flerp(b0, b1, t);
        clut[i] = (u16)(((DI_CLAMP(b, 0, 255) >> 3) << 10)
                      | ((DI_CLAMP(g, 0, 255) >> 3) << 5)
                      |  (DI_CLAMP(r, 0, 255) >> 3));
    }
}

void materials_init(void)
{
    synth_soil();
    synth_petal();
    /* Modulation ramps centred on 128: dark crack to lit clod crown, and
     * dark vein to pale blade rim. A slight hue tilt gives the soil its
     * reddish cast and the petal its cool one. */
    build_clut(g_clut_soil,  44, 36, 30, 236, 222, 206);
    build_clut(g_clut_petal, 40, 34, 64, 240, 232, 255);

    g_tpage = tpage_word(TEX_PAGE_X, TEX_PAGE_Y, ABR_HALF, TEX_4BIT);

    plat_upload_vram(TEX_PAGE_X + SOIL_U  / 4, TEX_PAGE_Y, TEX_W / 4, TEX_H, &g_soil[0][0]);
    plat_upload_vram(TEX_PAGE_X + PETAL_U / 4, TEX_PAGE_Y, TEX_W / 4, TEX_H, &g_petal[0][0]);
    plat_upload_vram(CLUT_X, SOIL_CLUT_Y,  16, 1, g_clut_soil);
    plat_upload_vram(CLUT_X, PETAL_CLUT_Y, 16, 1, g_clut_petal);
}

/* Day/night palette shift. Only the 16 CLUT entries are rewritten - 32 bytes
 * per texture - so the synthesised pattern is never rebuilt. */
void materials_set_night(s32 night)
{
    build_clut(g_clut_soil,
               flerp(44, 26, night), flerp(36, 26, night), flerp(30, 34, night),
               flerp(236, 180, night), flerp(222, 190, night), flerp(206, 226, night));
    build_clut(g_clut_petal,
               flerp(40, 28, night), flerp(34, 26, night), flerp(64, 70, night),
               flerp(240, 196, night), flerp(232, 206, night), flerp(255, 255, night));
    plat_upload_vram(CLUT_X, SOIL_CLUT_Y,  16, 1, g_clut_soil);
    plat_upload_vram(CLUT_X, PETAL_CLUT_Y, 16, 1, g_clut_petal);
}

u32 mat_soil_tpage(void)  { return g_tpage; }
u32 mat_soil_clut(void)   { return clut_word(CLUT_X, SOIL_CLUT_Y); }
u32 mat_petal_tpage(void) { return g_tpage; }
u32 mat_petal_clut(void)  { return clut_word(CLUT_X, PETAL_CLUT_Y); }
u32 mat_soil_u(void)      { return SOIL_U; }
u32 mat_petal_u(void)     { return PETAL_U; }
